=head2 Google::Cloud::Dialogflow::Cx::V3::Session::StreamingDetectIntentResponse

The top-level message returned from the
[StreamingDetectIntent][google.cloud.dialogflow.cx.v3.Sessions.StreamingDetectIntent]
method.

Multiple response messages can be returned in order:

*   If the `StreamingDetectIntentRequest.query_input.audio` field was
    set, the first M messages contain `recognition_result`.
    Each `recognition_result` represents a more complete transcript of what
    the user said. The last `recognition_result` has `is_final` set to
    `true`.

*   If the `StreamingDetectIntentRequest.enable_partial_response` field was
    true, the `detect_intent_response` field is populated for each
    of the following N responses, where 0 <= N <= 5.
    These responses set the
    [DetectIntentResponse.response_type][google.cloud.dialogflow.cx.v3.DetectIntentResponse.response_type]
    field to `PARTIAL`.

For the last response message, the `detect_intent_response` is fully
populated, and
[DetectIntentResponse.response_type][google.cloud.dialogflow.cx.v3.DetectIntentResponse.response_type]
is set to `FINAL`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->recognition_result() >> / C<< $msg->recognition_result($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::StreamingRecognitionResult>)

The result of speech recognition.

=item * C<< $msg->detect_intent_response() >> / C<< $msg->detect_intent_response($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::DetectIntentResponse>)

The response from detect intent.

=item * C<< $msg->debugging_info() >> / C<< $msg->debugging_info($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::CloudConversationDebuggingInfo>)

Debugging info that would get populated when
`StreamingDetectIntentRequest.enable_debugging_info` is set to true.

=back

=head2 Google::Cloud::Dialogflow::Cx::V3::Session::StreamingRecognitionResult

Contains a speech recognition result corresponding to a portion of the audio
that is currently being processed or an indication that this is the end
of the single requested utterance.

While end-user audio is being processed, Dialogflow sends a series of
results. Each result may contain a `transcript` value. A transcript
represents a portion of the utterance. While the recognizer is processing
audio, transcript values may be interim values or finalized values.
Once a transcript is finalized, the `is_final` value is set to true and
processing continues for the next transcript.

If `StreamingDetectIntentRequest.query_input.audio.config.single_utterance`
was true, and the recognizer has completed processing audio,
the `message_type` value is set to `END_OF_SINGLE_UTTERANCE and the
following (last) result contains the last finalized transcript.

The complete end-user utterance is determined by concatenating the
finalized transcript values received for the series of results.

In the following example, single utterance is enabled. In the case where
single utterance is not enabled, result 7 would not occur.

```
Num | transcript              | message_type            | is_final
--- | ----------------------- | ----------------------- | --------
1   | "tube"                  | TRANSCRIPT              | false
2   | "to be a"               | TRANSCRIPT              | false
3   | "to be"                 | TRANSCRIPT              | false
4   | "to be or not to be"    | TRANSCRIPT              | true
5   | "that's"                | TRANSCRIPT              | false
6   | "that is                | TRANSCRIPT              | false
7   | unset                   | END_OF_SINGLE_UTTERANCE | unset
8   | " that is the question" | TRANSCRIPT              | true
```

Concatenating the finalized transcripts with `is_final` set to true,
the complete utterance becomes "to be or not to be that is the question".

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->message_type() >> / C<< $msg->message_type($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::Cx::V3::StreamingRecognitionResult::MessageType>)

Type of the result message.

=item * C<< $msg->transcript() >> / C<< $msg->transcript($value) >>

Type: C<String>

Transcript text representing the words that the user spoke.
Populated if and only if `message_type` = `TRANSCRIPT`.

=item * C<< $msg->is_final() >> / C<< $msg->is_final($value) >>

Type: C<Bool>

If `false`, the `StreamingRecognitionResult` represents an
interim result that may change. If `true`, the recognizer will not return
any further hypotheses about this piece of the audio. May only be populated
for `message_type` = `TRANSCRIPT`.

=item * C<< $msg->confidence() >> / C<< $msg->confidence($value) >>

Type: C<Float>

The Speech confidence between 0.0 and 1.0 for the current portion of audio.
A higher number indicates an estimated greater likelihood that the
recognized words are correct. The default of 0.0 is a sentinel value
indicating that confidence was not set.

This field is typically only provided if `is_final` is true and you should
not rely on it being accurate or even set.

=item * C<< $msg->stability() >> / C<< $msg->stability($value) >>

Type: C<Float>

An estimate of the likelihood that the speech recognizer will
not change its guess about this interim recognition result:
* If the value is unspecified or 0.0, Dialogflow didn't compute the
  stability. In particular, Dialogflow will only provide stability for
  `TRANSCRIPT` results with `is_final = false`.
* Otherwise, the value is in (0.0, 1.0] where 0.0 means completely
  unstable and 1.0 means completely stable.

=item * C<< $msg->speech_word_info() >> / C<< $msg->speech_word_info($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::AudioConfig::SpeechWordInfo>)

Word-specific information for the words recognized by Speech in
[transcript][google.cloud.dialogflow.cx.v3.StreamingRecognitionResult.transcript].
Populated if and only if `message_type` = `TRANSCRIPT` and
[InputAudioConfig.enable_word_info] is set.

=item * C<< $msg->speech_end_offset() >> / C<< $msg->speech_end_offset($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Time offset of the end of this Speech recognition result relative to the
beginning of the audio. Only populated for `message_type` =
`TRANSCRIPT`.

=item * C<< $msg->language_code() >> / C<< $msg->language_code($value) >>

Type: C<String>

Detected language code for the transcript.

=back

=head3 Enum: StreamingRecognitionResult::MessageType

=over 4

=item * C<MESSAGE_TYPE_UNSPECIFIED> => C<0>

=item * C<TRANSCRIPT> => C<1>

=item * C<END_OF_SINGLE_UTTERANCE> => C<2>

=back

=head2 Google::Cloud::Dialogflow::Cx::V3::Session::QueryParameters

Represents the parameters of a conversational query.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->time_zone() >> / C<< $msg->time_zone($value) >>

Type: C<String>

The time zone of this conversational query from the [time zone
database](https://www.iana.org/time-zones), e.g., America/New_York,
Europe/Paris. If not provided, the time zone specified in the agent is
used.

=item * C<< $msg->geo_location() >> / C<< $msg->geo_location($value) >>

Type: C<Message> (L<Google::Type::Latlng::LatLng>)

The geo location of this conversational query.

=item * C<< $msg->session_entity_types() >> / C<< $msg->session_entity_types($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::SessionEntityType::SessionEntityType>)

Additional session entity types to replace or extend developer entity types
with. The entity synonyms apply to all languages and persist for the
session of this query.

=item * C<< $msg->payload() >> / C<< $msg->payload($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

This field can be used to pass custom data into the webhook associated with
the agent. Arbitrary JSON objects are supported.
Some integrations that query a Dialogflow agent may provide additional
information in the payload.
In particular, for the Dialogflow Phone Gateway integration, this field has
the form:
```
{
 "telephony": {
   "caller_id": "+18558363987"
 }
}
```

=item * C<< $msg->parameters() >> / C<< $msg->parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Additional parameters to be put into [session
parameters][SessionInfo.parameters]. To remove a
parameter from the session, clients should explicitly set the parameter
value to null.

You can reference the session parameters in the agent with the following
format: $session.params.parameter-id.

Depending on your protocol or client library language, this is a
map, associative array, symbol table, dictionary, or JSON object
composed of a collection of (MapKey, MapValue) pairs:

* MapKey type: string
* MapKey value: parameter name
* MapValue type: If parameter's entity type is a composite entity then use
map, otherwise, depending on the parameter value type, it could be one of
string, number, boolean, null, list or map.
* MapValue value: If parameter's entity type is a composite entity then use
map from composite entity property names to property values, otherwise,
use parameter value.

=item * C<< $msg->parameter_scope() >> / C<< $msg->parameter_scope($value) >>

Type: C<String>

Scope for the parameters. If not specified, parameters will be treated as
session parameters. Parameters with custom scope will not be put into
[session parameters][google.cloud.dialogflow.cx.v3.SessionInfo.parameters].

You can reference the parameters with custom scope in the agent with the
following format: $parameter-scope.params.parameter-id.

=item * C<< $msg->current_page() >> / C<< $msg->current_page($value) >>

Type: C<String>

The unique identifier of the [page][google.cloud.dialogflow.cx.v3.Page] to
override the [current page][QueryResult.current_page] in the session.
Format:
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/flows/<FlowID>/pages/<PageID>`.

If `current_page` is specified, the previous state of the session will be
ignored by Dialogflow, including the [previous
page][QueryResult.current_page] and the [previous session
parameters][QueryResult.parameters].
In most cases,
[current_page][google.cloud.dialogflow.cx.v3.QueryParameters.current_page]
and [parameters][google.cloud.dialogflow.cx.v3.QueryParameters.parameters]
should be configured together to direct a session to a specific state.

=item * C<< $msg->disable_webhook() >> / C<< $msg->disable_webhook($value) >>

Type: C<Bool>

Whether to disable webhook calls for this request.

=item * C<< $msg->analyze_query_text_sentiment() >> / C<< $msg->analyze_query_text_sentiment($value) >>

Type: C<Bool>

Configures whether sentiment analysis should be performed. If not
provided, sentiment analysis is not performed.

=item * C<< $msg->webhook_headers() >> / C<< $msg->webhook_headers($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::QueryParameters::WebhookHeadersEntry>)

This field can be used to pass HTTP headers for a webhook
call. These headers will be sent to webhook along with the headers that
have been configured through Dialogflow web console. The headers defined
within this field will overwrite the headers configured through Dialogflow
console if there is a conflict. Header names are case-insensitive.
Google's specified headers are not allowed. Including: "Host",
"Content-Length", "Connection", "From", "User-Agent", "Accept-Encoding",
"If-Modified-Since", "If-None-Match", "X-Forwarded-For", etc.

=item * C<< $msg->flow_versions() >> / C<< $msg->flow_versions($value) >>

Type: C<String>

A list of flow versions to override for the request.
Format:
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/flows/<FlowID>/versions/<VersionID>`.

If version 1 of flow X is included in this list, the traffic of
flow X will go through version 1 regardless of the version configuration in
the environment. Each flow can have at most one version specified in this
list.

=item * C<< $msg->current_playbook() >> / C<< $msg->current_playbook($value) >>

Type: C<String>

Optional. The unique identifier of the
[playbook][google.cloud.dialogflow.cx.v3.Playbook] to start or continue the
session with. If `current_playbook` is specified, the previous state of the
session will be ignored by Dialogflow.

Format:
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/playbooks/<PlaybookID>`.

=item * C<< $msg->llm_model_settings() >> / C<< $msg->llm_model_settings($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::GenerativeSettings::LlmModelSettings>)

Optional. Use the specified LLM model settings for processing the request.

=item * C<< $msg->channel() >> / C<< $msg->channel($value) >>

Type: C<String>

The channel which this query is for.

If specified, only the
[ResponseMessage][google.cloud.dialogflow.cx.v3.ResponseMessage] associated
with the channel will be returned. If no
[ResponseMessage][google.cloud.dialogflow.cx.v3.ResponseMessage] is
associated with the channel, it falls back to the
[ResponseMessage][google.cloud.dialogflow.cx.v3.ResponseMessage] with
unspecified channel.

If unspecified, the
[ResponseMessage][google.cloud.dialogflow.cx.v3.ResponseMessage] with
unspecified channel will be returned.

=item * C<< $msg->session_ttl() >> / C<< $msg->session_ttl($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Optional. Configure lifetime of the Dialogflow session.
By default, a Dialogflow session remains active and its data is stored for
30 minutes after the last request is sent for the session.
This value should be no longer than 1 day.

=item * C<< $msg->end_user_metadata() >> / C<< $msg->end_user_metadata($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Optional. Information about the end-user to improve the relevance and
accuracy of generative answers.

This will be interpreted and used by a language model, so, for good
results, the data should be self-descriptive, and in a simple structure.

Example:

```json
{
  "subscription plan": "Business Premium Plus",
  "devices owned": [
    {"model": "Google Pixel 7"},
    {"model": "Google Pixel Tablet"}
  ]
}
```

=item * C<< $msg->search_config() >> / C<< $msg->search_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::SearchConfig>)

Optional. Search configuration for UCS search queries.

=item * C<< $msg->populate_data_store_connection_signals() >> / C<< $msg->populate_data_store_connection_signals($value) >>

Type: C<Bool>

Optional. If set to true and data stores are involved in serving the
request then
DetectIntentResponse.query_result.data_store_connection_signals
will be filled with data that can help evaluations.

=back

