=head2 Google::Cloud::Dialogflow::Cx::V3::Session::QueryInput

Represents the query input. It can contain one of:

1. A conversational query in the form of text.

2. An intent query that specifies which intent to trigger.

3. Natural language speech audio to be processed.

4. An event to be triggered.

5. DTMF digits to invoke an intent and fill in parameter value.

6. The results of a tool executed by the client.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->text() >> / C<< $msg->text($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::TextInput>)

The natural language text to be processed.

=item * C<< $msg->intent() >> / C<< $msg->intent($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::IntentInput>)

The intent to be triggered.

=item * C<< $msg->audio() >> / C<< $msg->audio($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::AudioInput>)

The natural language speech audio to be processed.

=item * C<< $msg->event() >> / C<< $msg->event($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::EventInput>)

The event to be triggered.

=item * C<< $msg->dtmf() >> / C<< $msg->dtmf($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::DtmfInput>)

The DTMF event to be handled.

=item * C<< $msg->tool_call_result() >> / C<< $msg->tool_call_result($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::ToolCall::ToolCallResult>)

The results of a tool executed by the client.

=item * C<< $msg->language_code() >> / C<< $msg->language_code($value) >>

Type: C<String>

Required. The language of the input. See [Language
Support](https://cloud.google.com/dialogflow/cx/docs/reference/language)
for a list of the currently supported language codes. Note that queries in
the same session do not necessarily need to specify the same language.

=back

