=head2 Google::Cloud::Dialogflow::Cx::V3::Session::Match

Represents one match result of [MatchIntent][].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->intent() >> / C<< $msg->intent($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Intent::Intent>)

The [Intent][google.cloud.dialogflow.cx.v3.Intent] that matched the query.
Some, not all fields are filled in this message, including but not limited
to: `name` and `display_name`. Only filled for
[`INTENT`][google.cloud.dialogflow.cx.v3.Match.MatchType] match type.

=item * C<< $msg->event() >> / C<< $msg->event($value) >>

Type: C<String>

The event that matched the query. Filled for
[`EVENT`][google.cloud.dialogflow.cx.v3.Match.MatchType],
[`NO_MATCH`][google.cloud.dialogflow.cx.v3.Match.MatchType] and
[`NO_INPUT`][google.cloud.dialogflow.cx.v3.Match.MatchType] match types.

=item * C<< $msg->parameters() >> / C<< $msg->parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

The collection of parameters extracted from the query.

Depending on your protocol or client library language, this is a
map, associative array, symbol table, dictionary, or JSON object
composed of a collection of (MapKey, MapValue) pairs:

* MapKey type: string
* MapKey value: parameter name
* MapValue type: If parameter's entity type is a composite entity then use
map, otherwise, depending on the parameter value type, it could be one of
string, number, boolean, null, list or map.
* MapValue value: If parameter's entity type is a composite entity then use
map from composite entity property names to property values, otherwise,
use parameter value.

=item * C<< $msg->resolved_input() >> / C<< $msg->resolved_input($value) >>

Type: C<String>

Final text input which was matched during MatchIntent. This value can be
different from original input sent in request because of spelling
correction or other processing.

=item * C<< $msg->match_type() >> / C<< $msg->match_type($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::Cx::V3::Match::MatchType>)

Type of this [Match][google.cloud.dialogflow.cx.v3.Match].

=item * C<< $msg->confidence() >> / C<< $msg->confidence($value) >>

Type: C<Float>

The confidence of this match. Values range from 0.0 (completely uncertain)
to 1.0 (completely certain).
This value is for informational purpose only and is only used to help match
the best intent within the classification threshold. This value may change
for the same end-user expression at any time due to a model retraining or
change in implementation.

=back

=head3 Enum: Match::MatchType

=over 4

=item * C<MATCH_TYPE_UNSPECIFIED> => C<0>

=item * C<INTENT> => C<1>

=item * C<DIRECT_INTENT> => C<2>

=item * C<PARAMETER_FILLING> => C<3>

=item * C<NO_MATCH> => C<4>

=item * C<NO_INPUT> => C<5>

=item * C<EVENT> => C<6>

=item * C<KNOWLEDGE_CONNECTOR> => C<8>

=item * C<PLAYBOOK> => C<9>

=back

=head2 Google::Cloud::Dialogflow::Cx::V3::Session::MatchIntentRequest

Request of [MatchIntent][].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->session() >> / C<< $msg->session($value) >>

Type: C<String>

Required. The name of the session this query is sent to.
Format:
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/sessions/<SessionID>`
or
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/environments/<EnvironmentID>/sessions/<SessionID>`.
If `Environment ID` is not specified, we assume default 'draft'
environment.
It's up to the API caller to choose an appropriate `Session ID`. It can be
a random number or some type of session identifiers (preferably hashed).
The length of the `Session ID` must not exceed 36 characters.

For more information, see the [sessions
guide](https://cloud.google.com/dialogflow/cx/docs/concept/session).

=item * C<< $msg->query_params() >> / C<< $msg->query_params($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::QueryParameters>)

The parameters of this query.

=item * C<< $msg->query_input() >> / C<< $msg->query_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::QueryInput>)

Required. The input specification.

=item * C<< $msg->persist_parameter_changes() >> / C<< $msg->persist_parameter_changes($value) >>

Type: C<Bool>

Persist session parameter changes from `query_params`.

=back

=head2 Google::Cloud::Dialogflow::Cx::V3::Session::MatchIntentResponse

Response of [MatchIntent][].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->text() >> / C<< $msg->text($value) >>

Type: C<String>

If [natural language text][google.cloud.dialogflow.cx.v3.TextInput] was
provided as input, this field will contain a copy of the text.

=item * C<< $msg->trigger_intent() >> / C<< $msg->trigger_intent($value) >>

Type: C<String>

If an [intent][google.cloud.dialogflow.cx.v3.IntentInput] was provided as
input, this field will contain a copy of the intent identifier. Format:
`projects/<ProjectID>/locations/<LocationID>/agents/<AgentID>/intents/<IntentID>`.

=item * C<< $msg->transcript() >> / C<< $msg->transcript($value) >>

Type: C<String>

If [natural language speech
audio][google.cloud.dialogflow.cx.v3.AudioInput] was provided as input,
this field will contain the transcript for the audio.

=item * C<< $msg->trigger_event() >> / C<< $msg->trigger_event($value) >>

Type: C<String>

If an [event][google.cloud.dialogflow.cx.v3.EventInput] was provided as
input, this field will contain a copy of the event name.

=item * C<< $msg->matches() >> / C<< $msg->matches($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::Match>)

Match results, if more than one, ordered descendingly by the confidence
we have that the particular intent matches the query.

=item * C<< $msg->current_page() >> / C<< $msg->current_page($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Page::Page>)

The current [Page][google.cloud.dialogflow.cx.v3.Page]. Some, not all
fields are filled in this message, including but not limited to `name` and
`display_name`.

=back

