=item * C<< $msg->match() >> / C<< $msg->match($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::Match>)

The matched intent/event to fulfill.

=item * C<< $msg->output_audio_config() >> / C<< $msg->output_audio_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::AudioConfig::OutputAudioConfig>)

Instructs the speech synthesizer how to generate output audio.

