=head2 Google::Cloud::Dialogflow::Cx::V3::Session::FulfillIntentResponse

Response of [FulfillIntent][]

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->response_id() >> / C<< $msg->response_id($value) >>

Type: C<String>

Output only. The unique identifier of the response. It can be used to
locate a response in the training example set or for reporting issues.

=item * C<< $msg->query_result() >> / C<< $msg->query_result($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::Session::QueryResult>)

The result of the conversational query.

=item * C<< $msg->output_audio() >> / C<< $msg->output_audio($value) >>

Type: C<Bytes>

The audio data bytes encoded as specified in the request.
Note: The output audio is generated based on the values of default platform
text responses found in the
[`query_result.response_messages`][google.cloud.dialogflow.cx.v3.QueryResult.response_messages]
field. If multiple default text responses exist, they will be concatenated
when generating audio. If no default platform text responses exist, the
generated audio content will be empty.

In some scenarios, multiple output audio fields may be present in the
response structure. In these cases, only the top-most-level audio output
has content.

=item * C<< $msg->output_audio_config() >> / C<< $msg->output_audio_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::Cx::V3::AudioConfig::OutputAudioConfig>)

The config used by the speech synthesizer to generate the output audio.

=back

=head2 Google::Cloud::Dialogflow::Cx::V3::Session::SentimentAnalysisResult

The result of sentiment analysis. Sentiment analysis inspects user input
and identifies the prevailing subjective opinion, especially to determine a
user's attitude as positive, negative, or neutral.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->score() >> / C<< $msg->score($value) >>

Type: C<Float>

Sentiment score between -1.0 (negative sentiment) and 1.0 (positive
 sentiment).

=item * C<< $msg->magnitude() >> / C<< $msg->magnitude($value) >>

Type: C<Float>

A non-negative number in the [0, +inf) range, which represents the absolute
magnitude of sentiment, regardless of score (positive or negative).

=back

